css:
.event-pass {
    width: 90mm;
    height: 140mm;

    margin: 0 auto;

    position: relative;
    overflow: hidden;

    box-sizing: border-box;

    background: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    color: #1c2453;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


/* =========================
   TOP DECORATION
========================= */

.top-accent {
    position: relative;

    height: 28mm;

    overflow: hidden;

    background:
        linear-gradient(
            to bottom,
            #c7f2ff 0%,
            #eafcff 55%,
            #ffffff 100%
        );

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


.wave {
    position: absolute;

    left: -10%;
    width: 120%;

    border-radius: 50%;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


.wave-one {
    top: 13mm;

    height: 15mm;

    background: rgba(255, 196, 103, 0.35);

    transform: rotate(-4deg);
}


.wave-two {
    top: 16mm;

    height: 13mm;

    background: rgba(108, 118, 170, 0.18);

    transform: rotate(2deg);
}


.wave-three {
    top: 20mm;

    height: 10mm;

    background: #343678;

    border-radius: 0;

    box-shadow:
        0 5mm 10mm rgba(0, 188, 212, 0.45);
}


/* =========================
   PARTICIPANT AREA
========================= */

.participant-section {
    padding: 11mm 8mm 0;

    text-align: center;
}


.participant-name {
    margin-top: 3mm;
    margin-bottom: 2mm;

    font-size: 22px;
    font-weight: 700;

    line-height: 1.15;

    color: #1b2354;
}


.participant-info {
    margin-bottom: 1mm;

    font-size: 10px;

    color: #555555;
}


.participant-type {
    margin-top: 6mm;
    margin-bottom: 4mm;

    font-size: 11px;
    font-weight: 700;

    letter-spacing: 0.8px;

    color: #343678;
}


.qr-wrapper {
    width: 40mm;
    height: 40mm;

    margin: 0 auto 3mm;

    display: flex;

    align-items: center;
    justify-content: center;
}


.qr-wrapper img {
    display: block;

    width: 38mm !important;
    height: 38mm !important;

    object-fit: contain;
}


.participant-id {
    margin-top: 2mm;

    font-size: 12px;
    font-weight: 700;

    color: #1b2354;
}


.scan-label {
    margin-top: 1.5mm;

    font-size: 7px;
    font-weight: 600;

    letter-spacing: 0.8px;

    color: #777777;
}


/* =========================
   BOTTOM AREA
========================= */

.bottom-section {
    position: absolute;

    left: 7mm;
    right: 7mm;
    bottom: 8mm;

    text-align: left;
}


.bottom-line {
    width: 100%;
    height: 1px;

    margin-bottom: 3mm;

    background: #7a7a7a;
}


.event-name {
    font-size: 9px;
    font-weight: 700;

    color: #222222;
}


.footer-note {
    margin-top: 1mm;

    font-size: 7px;

    color: #666666;

    text-transform: uppercase;

    letter-spacing: 0.5px;
}


/* =========================
   BOTTOM COLOR STRIP
========================= */

.bottom-accent {
    position: absolute;

    left: 0;
    right: 0;
    bottom: 0;

    height: 3mm;

    display: flex;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


.accent-red {
    width: 40%;

    background: #b9433d;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


.accent-blue {
    width: 43%;

    background: #343678;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


.accent-yellow {
    width: 17%;

    background: #f0c445;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


/* =========================
   PRINT PAGE SIZE
========================= */

@page {
    size: 90mm 140mm !important;
    margin: 0 !important;
}


/* =========================
   PRINT
========================= */

@media print {

    html,
    body {
        width: 90mm !important;
        height: 140mm !important;

        margin: 0 !important;
        padding: 0 !important;

        overflow: hidden !important;

        background: #ffffff !important;

        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }


    .print-format {
        width: 90mm !important;
        height: 140mm !important;
        min-height: 140mm !important;

        max-width: 90mm !important;

        margin: 0 !important;
        padding: 0 !important;

        box-sizing: border-box !important;

        background: transparent !important;

        page-break-after: avoid !important;
        page-break-before: avoid !important;
        page-break-inside: avoid !important;
    }


    .event-pass {
        width: 90mm !important;
        height: 140mm !important;

        min-width: 90mm !important;
        min-height: 140mm !important;

        max-width: 90mm !important;
        max-height: 140mm !important;

        margin: 0 !important;
        padding: 0 !important;

        position: relative !important;

        overflow: hidden !important;

        box-sizing: border-box !important;

        background: #ffffff !important;

        page-break-after: avoid !important;
        page-break-before: avoid !important;
        page-break-inside: avoid !important;

        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }


    .top-accent,
    .wave,
    .wave-one,
    .wave-two,
    .wave-three,
    .bottom-accent,
    .accent-red,
    .accent-blue,
    .accent-yellow {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }


    .qr-wrapper img {
        width: 38mm !important;
        height: 38mm !important;

        max-width: 38mm !important;
        max-height: 38mm !important;
    }
}
